	obj.YtMint = accountKeys[indices[indexOffset]]
	indexOffset++
	// Set user_underlying account from index
	if indices[indexOffset] >= uint8(len(accountKeys)) {
		return fmt.Errorf("account index %d for %s is out of bounds (max: %d)", indices[indexOffset], "user_underlying", len(accountKeys)-1)
	}
	obj.UserUnderlying = accountKeys[indices[indexOffset]]
	indexOffset++
